import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"我的钱包 - 代金券","description":"","frontmatter":{"title":"我的钱包 - 代金券"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/wallet-vouchers.md","filePath":"ops-knowledge-base/presales-support/wallet-vouchers.md","lastUpdated":1788259091000}'),o={name:"ops-knowledge-base/presales-support/wallet-vouchers.md"};function s(i,a,n,p,h,d){return t(),r("div",null,[...a[0]||(a[0]=[l('<h2 id="一、功能概述" tabindex="-1">一、功能概述 <a class="header-anchor" href="#一、功能概述" aria-label="Permalink to &quot;一、功能概述&quot;">​</a></h2><p>代金券是平台提供的资金优惠工具，可用于抵扣对应产品的消费金额，帮助用户降低使用成本。财务管理模块的 “代金券” 页面支持代金券的查询、筛选及使用操作。</p><h2 id="二、功能入口" tabindex="-1">二、功能入口 <a class="header-anchor" href="#二、功能入口" aria-label="Permalink to &quot;二、功能入口&quot;">​</a></h2><p>通过导航路径 <strong>客户中心 / 财务管理</strong> 进入页面后，点击顶部标签栏的 “代金券”，即可进入代金券管理界面。</p><h2 id="三、功能说明" tabindex="-1">三、功能说明 <a class="header-anchor" href="#三、功能说明" aria-label="Permalink to &quot;三、功能说明&quot;">​</a></h2><h3 id="一-筛选与配置" tabindex="-1">（一）筛选与配置 <a class="header-anchor" href="#一-筛选与配置" aria-label="Permalink to &quot;（一）筛选与配置&quot;">​</a></h3><ol><li><strong>状态筛选</strong>：通过 “状态” 下拉框，可选择 “全部状态”“未使用”“已过期”“已使用”“未生效”，快速筛选对应状态的代金券。</li><li><strong>适用产品筛选</strong>：通过 “适用产品” 下拉框，可选择 “全部产品”“VPS”“云机”“物理服务器” 等，筛选适用于特定产品的代金券。</li><li><strong>保留配置</strong>：完成筛选条件选择后，点击 “保留当前配置” 按钮，可固定当前筛选条件，便于后续直接查看目标代金券。</li></ol><h3 id="二-代金券列表信息" tabindex="-1">（二）代金券列表信息 <a class="header-anchor" href="#二-代金券列表信息" aria-label="Permalink to &quot;（二）代金券列表信息&quot;">​</a></h3><p>列表展示代金券的核心信息：</p><ul><li><p><strong>名称</strong>：代金券的活动标识（如 “双旦预充值膨胀金”）。</p></li><li><p><strong>金额</strong>：代金券的可抵扣金额。</p></li><li><p><strong>状态</strong>：代金券当前的使用状态（如 “未使用”）。</p></li><li><p><strong>生效日期 / 到期日期</strong>：代金券可使用的时间范围，需在有效期内使用。</p></li><li><p><strong>操作</strong>：</p><ul><li>“去使用”：点击可跳转至对应产品的购买 / 续费页面，使用该代金券抵扣金额。</li><li>“交易记录”：点击可查看该代金券的使用、发放等交易明细。</li></ul></li></ul><h3 id="三-分页浏览" tabindex="-1">（三）分页浏览 <a class="header-anchor" href="#三-分页浏览" aria-label="Permalink to &quot;（三）分页浏览&quot;">​</a></h3><p>界面底部支持分页查看更多代金券记录，可通过 “上一页”“下一页” 按钮切换页码。</p>',12)])])}const g=e(o,[["render",s]]);export{u as __pageData,g as default};
